def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}
    history = []
    rejected = []
    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(s):
        if not s or not s.isascii() or not s.isdigit():
            return None

        # Small chunks also support amounts beyond Python's int-string limit.
        value = 0
        for start in range(0, len(s), 9):
            chunk = s[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if len(tokens) != arities.get(verb) or not all(tokens):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        name = tokens[1]
        current = accounts.get(name)
        changes = None

        if verb in ("freeze", "unfreeze"):
            target_frozen = verb == "freeze"
            if current is not None and current[1] != target_frozen:
                changes = ((name, (current[0], target_frozen)),)
        else:
            amount = parse_amount(tokens[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

            if verb == "open":
                if current is None:
                    changes = ((name, (amount, False)),)

            elif current is not None:
                balance, frozen = current

                if verb == "deposit":
                    changes = ((name, (balance + amount, frozen)),)

                elif verb == "withdraw":
                    if not frozen and balance >= amount:
                        changes = ((name, (balance - amount, frozen)),)

                elif verb == "transfer":
                    destination = tokens[2]
                    target = accounts.get(destination)
                    if (
                        destination != name
                        and target is not None
                        and not frozen
                        and balance >= amount
                    ):
                        changes = (
                            (name, (balance - amount, frozen)),
                            (destination, (target[0] + amount, target[1])),
                        )

        if changes is None:
            rejected.append(index)
            continue

        history.append(tuple(
            (account, accounts.get(account))
            for account, _ in changes
        ))
        accounts.update(changes)

    balances = {name: state[0] for name, state in accounts.items()}
    return balances, rejected
